import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Link, NavLink, Route, Routes, useLocation, useNavigate, useSearchParams } from "react-router-dom";
import {
  Activity, ArrowDownToLine, ArrowLeft, ArrowRight, BarChart3, BookOpen, Check, CircleHelp,
  ClipboardList, Clock3, FileBarChart, FileText, Gauge, LogOut, Menu, Plus, Search, Settings as SettingsIcon,
  ShieldCheck, Users, Video, X,
} from "lucide-react";
import { api, apiBlob, apiPage, ApiError, download, login, register } from "./api";

type Athlete = { id: number; first_name: string; last_name: string; identification: string; age: number; gender: string; email?: string|null; category?: string|null; group_name?: string|null; is_active:boolean; test_count?:number };
type Test = { id: number; athlete_id: number; distance: number; test_type: string; technique: string; status: string; analysis_status?:string|null; average_speed?:number|null; maximum_speed?:number|null; stride_length?:number|null; cadence?:number|null; posture_score?:number|null; created_at?: string };
type Analysis = { id: number; video_id: number; status: string; progress_percentage: number; error_message?: string };
type Metrics = { analysis_id: number; average_speed: number; maximum_speed: number; stride_length: number; cadence: number; posture_score: number };
type FrameDatum = {frame_number:number;timestamp:number;x_position:number;y_position:number;speed:number;stride_phase:string;posture_score:number;keypoints:Array<{name:string;x:number;y:number;confidence:number}>};
type AnalysisFrames = {analysis_id:number;video_id:number|null;width:number|null;height:number|null;duration:number|null;frames:FrameDatum[]};
type Dashboard = { total_athletes: number; total_tests: number; completed_tests: number; processing_tests: number; recent_analyses: Array<{test_id:number; athlete_name:string;distance:number;test_type:string;status:string;average_speed:number|null;created_at:string;analysis_id:number|null}> };
type Resource = { id: number; type: string; title: string; category: string; filename: string; size_bytes: number; created_at: string; download_url: string };
type Report = { id: number; analysis_id: number; name: string; format: string; created_at: string; download_url: string; downloads?:number };
type ReferenceRange = { id:number; metric:string; unit:string; age_range:string; low:string; average:string; high:string; source:string };
type CurrentUser = { email:string; full_name:string; phone:string|null; role:"docente"|"estudiante" };

const navItems = [
  { to: "/", label: "Panel", icon: BarChart3 },
  { to: "/analisis", label: "Análisis", icon: Activity },
  { to: "/atletas", label: "Atletas", icon: Users },
  { to: "/pruebas", label: "Pruebas", icon: ClipboardList },
  { to: "/reportes", label: "Reportes", icon: FileBarChart },
  { to: "/biblioteca", label: "Biblioteca", icon: BookOpen },
  { to: "/configuracion", label: "Configuración", icon: SettingsIcon },
];

function App() {
  const [authorized, setAuthorized] = useState(Boolean(localStorage.getItem("athletic-token")));
  const [currentUser,setCurrentUser]=useState<CurrentUser|null>(null);const [profileError,setProfileError]=useState("");
  const [mobileMenu, setMobileMenu] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const active = navItems.find((item) => item.to === location.pathname);
  const logout = () => { localStorage.removeItem("athletic-token"); setCurrentUser(null); setAuthorized(false); };
  useEffect(()=>{if(!authorized){setCurrentUser(null);return;}let mounted=true;api<CurrentUser>("/auth/me").then(user=>{if(mounted){setCurrentUser(user);setProfileError("");}}).catch(error=>{if(mounted)setProfileError(message(error));});return()=>{mounted=false;};},[authorized]);

  if (!authorized) return <Login onLogin={() => { setAuthorized(true); navigate("/"); }} />;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileMenu ? "sidebar-open" : ""}`}>
      <div className="brand"><span className="brand-mark"><Activity size={19} /></span><span>ATHLETIC<br /><b>ANALYSIS</b></span></div>
      <div className="nav-caption">MENÚ PRINCIPAL</div>
      <nav>{navItems.map(({to,label,icon:Icon}) => <NavLink key={to} to={to} end={to === "/"} onClick={() => setMobileMenu(false)} className={({isActive}) => `nav-link ${isActive ? "active" : ""}`}><Icon size={18} /><span>{label}</span>{label === "Análisis" && <span className="nav-dot" />}</NavLink>)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><CircleHelp size={18}/><span><b>¿Necesitas ayuda?</b><small>Consulta la guía de uso</small></span><ArrowRight size={15}/></div><button className="nav-link logout" onClick={logout}><LogOut size={18}/><span>Cerrar sesión</span></button><div className="profile-mini"><div className="avatar">{currentUser?initialsFromName(currentUser.full_name):"…"}</div><span><b>{currentUser?.full_name??"Cargando perfil…"}</b><small>{currentUser?roleLabel(currentUser.role):" "}</small></span></div></div>
    </aside>
    {mobileMenu && <button className="scrim" aria-label="Cerrar menú" onClick={() => setMobileMenu(false)} />}
    <main className="main-area">
      <header className="topbar"><button className="icon-button mobile-toggle" onClick={() => setMobileMenu(!mobileMenu)} aria-label="Abrir menú"><Menu size={20}/></button><div className="breadcrumbs">Inicio <span>/</span> <b>{active?.label ?? "Detalle"}</b></div><div className="top-actions"><span className="live-dot"/> Sistema operativo <span>{currentUser?roleLabel(currentUser.role):""}</span><div className="avatar avatar-small">{currentUser?initialsFromName(currentUser.full_name):"…"}</div></div></header>
      <div className="page-wrap">{profileError&&<ErrorBanner text={profileError}/>}<Routes>
        <Route path="/" element={<DashboardPage currentUser={currentUser}/>}/>
        <Route path="/analisis" element={<AnalysisPage/>}/>
        <Route path="/atletas" element={<AthletesPage/>}/>
        <Route path="/atletas/:id" element={<AthleteDetail/>}/>
        <Route path="/pruebas" element={<TestsPage/>}/>
        <Route path="/reportes" element={<ReportsPage/>}/>
        <Route path="/biblioteca" element={<LibraryPage/>}/>
        <Route path="/configuracion" element={<SettingsPage onProfileUpdated={setCurrentUser}/>}/>
        <Route path="*" element={<Empty title="Página no encontrada" detail="La sección solicitada no existe."/>}/>
      </Routes></div>
    </main>
  </div>;
}

function Login({onLogin}:{onLogin:()=>void}) {
  const [mode,setMode]=useState<"login"|"register">("login");const [fullName,setFullName]=useState("");const [email,setEmail]=useState(()=>localStorage.getItem("athletic-last-email")??"");const [phone,setPhone]=useState(""); const [password,setPassword]=useState("");const [confirmPassword,setConfirmPassword]=useState("");const [role,setRole]=useState<"docente"|"estudiante">("docente"); const [error,setError]=useState(""); const [busy,setBusy]=useState(false);
  async function submit(e:React.FormEvent<HTMLFormElement>) { e.preventDefault(); setError("");if(mode==="register"&&password!==confirmPassword){setError("Las contraseñas no coinciden.");return;}const submitted=new FormData(e.currentTarget);const submittedEmail=String(submitted.get("email")??email);const submittedPassword=String(submitted.get("password")??password);setBusy(true);try{if(mode==="register")await register(fullName,submittedEmail,phone,submittedPassword,role);else await login(submittedEmail,submittedPassword);localStorage.setItem("athletic-last-email",submittedEmail);onLogin();} catch(err) {setError(message(err));} finally {setBusy(false);} }
  return <div className="login-page"><div className="login-brand"><span className="brand-mark"><Activity/></span><span>ATHLETIC <b>ANALYSIS</b></span></div><form className="login-card" onSubmit={submit} autoComplete="on"><span className="eyebrow">PLATAFORMA DE RENDIMIENTO</span><h1>{mode==="register"?"Crear cuenta":"Bienvenido"}</h1><p>{mode==="register"?"Regístrate para acceder a la plataforma.":"Ingresa a tu espacio de análisis deportivo."}</p>{mode==="register"&&<><label>Nombre completo<input type="text" value={fullName} onChange={e=>setFullName(e.target.value)} required minLength={2} maxLength={255} autoComplete="name" placeholder="Nombre y apellidos"/></label><label>Cargo<select value={role} onChange={e=>setRole(e.target.value as "docente"|"estudiante")}><option value="docente">Docente</option><option value="estudiante">Estudiante</option></select></label></>}<label>Correo electrónico<input type="email" name="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete={mode==="register"?"email":"username"} placeholder="entrenador@institucion.edu"/></label>{mode==="register"&&<label>Teléfono<input type="tel" value={phone} onChange={e=>setPhone(e.target.value)} required minLength={7} maxLength={20} pattern="\\+?[0-9\\s().-]{7,20}" autoComplete="tel" placeholder="+57 300 123 4567"/></label>}<label>Contraseña<input type="password" name="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={mode==="register"?10:1} maxLength={72} autoComplete={mode==="register"?"new-password":"current-password"} placeholder={mode==="register"?"Mínimo 10 caracteres":"••••••••"}/></label>{mode==="register"&&<label>Confirmar contraseña<input type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} required minLength={10} maxLength={72} autoComplete="new-password" placeholder="Repite la contraseña"/></label>}{error&&<ErrorBanner text={error}/>}<button className="button primary full" disabled={busy}>{busy?(mode==="register"?"Creando cuenta…":"Ingresando…"):(mode==="register"?"Crear cuenta":"Iniciar sesión")} <ArrowRight size={17}/></button><button type="button" className="text-link" onClick={()=>{setMode(mode==="login"?"register":"login");setError("");}}>{mode==="register"?"¿Ya tienes cuenta? Inicia sesión":"¿No tienes cuenta? Crear cuenta"}</button>{mode==="login"&&<small className="login-note">Acceso para docentes y estudiantes</small>}</form><div className="login-foot">ATHLETIC ANALYSIS · RENDIMIENTO BASADO EN DATOS</div></div>;
}

function DashboardPage({currentUser}:{currentUser:CurrentUser|null}) {
  const [data,setData]=useState<Dashboard|null>(null); const [error,setError]=useState("");
  useEffect(()=>{api<Dashboard>("/dashboard/stats").then(setData).catch(e=>setError(message(e)));},[]);
  return <><div className="welcome-row"><div><span className="eyebrow">PANEL PRINCIPAL</span><h1>¡Bienvenido{currentUser?`, ${currentUser.full_name.split(" ")[0]}`:" de nuevo"}!</h1><p>Un resumen claro del rendimiento y progreso de tus atletas.</p></div><Link className="button primary" to="/analisis"><Plus size={18}/> Nuevo análisis</Link></div>
    {error&&<ErrorBanner text={error}/>}
    <section className="hero-card"><div className="hero-copy"><span className="hero-kicker">ANÁLISIS DE RENDIMIENTO</span><h2>El siguiente récord<br/>empieza con un dato.</h2><p>Evalúa la técnica, entiende el movimiento y acompaña cada paso del progreso.</p><Link className="button white-button" to="/analisis">Comenzar análisis <ArrowRight size={16}/></Link></div><div className="runner-art"><div className="runner-circle"><Activity size={76}/><span className="runner-orbit orbit-one"/><span className="runner-orbit orbit-two"/></div><div className="hero-float"><Gauge size={17}/><span><b>Biomecánica</b><small>en cada zancada</small></span></div></div></section>
    <div className="section-heading"><div><span className="eyebrow">VISTA GENERAL</span><h2>Tu actividad</h2></div><span className="muted">Actualizado en tiempo real</span></div>
    <div className="stat-grid"><StatCard label="Atletas registrados" value={data?.total_athletes} icon={<Users/>} color="blue" note="En tu institución"/><StatCard label="Pruebas realizadas" value={data?.total_tests} icon={<ClipboardList/>} color="violet" note="Historial completo"/><StatCard label="Completadas" value={data?.completed_tests} icon={<Check/>} color="green" note="Análisis listos"/><StatCard label="En proceso" value={data?.processing_tests} icon={<Clock3/>} color="amber" note="Procesando video"/> </div>
    <section className="panel recent-panel"><div className="panel-heading"><div><h2>Últimos análisis</h2><p>Actividad reciente de tus atletas</p></div><Link className="text-link" to="/pruebas">Ver todas <ArrowRight size={15}/></Link></div>
      {data?.recent_analyses?.length ? <div className="recent-list">{data.recent_analyses.map((item)=><div className="recent-row" key={item.test_id}><div className="recent-icon"><Activity size={18}/></div><div className="recent-name"><b>{item.athlete_name}</b><small>{item.distance} m · {item.test_type}</small></div><div className="recent-date">{formatDate(item.created_at)}</div><div className="recent-speed">{item.average_speed == null?"—":`${item.average_speed.toFixed(2)} m/s`}<small>Vel. promedio</small></div><StatusBadge status={item.status}/>{item.analysis_id&&<Link className="row-arrow" to={`/analisis?analysis=${item.analysis_id}`} aria-label="Ver análisis"><ArrowRight size={16}/></Link>}</div>)}</div> : <Empty title="Aún no hay análisis" detail="Carga el primer video para ver resultados y métricas aquí." action={<Link className="button primary" to="/analisis"><Plus size={16}/> Nuevo análisis</Link>}/>}</section>
    <section className="learn-section"><div className="learn-title"><span className="eyebrow">BIOMECÁNICA</span><h2>¿Qué analizamos?</h2><p>Transformamos cada movimiento en información útil para mejorar.</p></div><div className="learn-grid"><LearnCard icon={<Activity/>} title="Velocidad" desc="Ritmo y aceleración durante la carrera." color="blue"/><LearnCard icon={<ArrowRight/>} title="Longitud de zancada" desc="Distancia cubierta en cada paso." color="violet"/><LearnCard icon={<Gauge/>} title="Cadencia" desc="Frecuencia y regularidad de apoyos." color="amber"/><LearnCard icon={<ShieldCheck/>} title="Postura" desc="Alineación y eficiencia del movimiento." color="green"/></div></section>
  </>;
}

function AnalysisPage() {
  const [searchParams,setSearchParams]=useSearchParams();
  const [athletes,setAthletes]=useState<Athlete[]>([]); const [selected,setSelected]=useState(searchParams.get("athlete")??""); const [name,setName]=useState(""); const [identification,setIdentification]=useState("");const [athleteAge,setAthleteAge]=useState("18");const [athleteGender,setAthleteGender]=useState("No especificado"); const [date,setDate]=useState(new Date().toISOString().slice(0,10)); const [distance,setDistance]=useState("10"); const [testType,setTestType]=useState("Carrera de velocidad"); const [technique,setTechnique]=useState("Salida de tacos"); const [file,setFile]=useState<File|null>(null);const [preview,setPreview]=useState(false);const [previewSrc,setPreviewSrc]=useState("");const [videoInfo,setVideoInfo]=useState({duration:0,width:0,height:0}); const [analysis,setAnalysis]=useState<Analysis|null>(null); const [metrics,setMetrics]=useState<Metrics|null>(null); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  const [frameData,setFrameData]=useState<AnalysisFrames|null>(null);const [videoSrc,setVideoSrc]=useState("");const [currentTime,setCurrentTime]=useState(0);const [comparisons,setComparisons]=useState<Analysis[]>([]);const [compareId,setCompareId]=useState("");const [comparison,setComparison]=useState<Record<string,{current:number;comparison:number;difference:number}>|null>(null);const [draggingVideo,setDraggingVideo]=useState(false);const player=useRef<HTMLVideoElement>(null);
  useEffect(()=>{api<Athlete[]>("/atletas").then(setAthletes).catch(e=>setError(message(e)));},[]);
  useEffect(()=>{if(!file){setPreviewSrc("");return;}const url=URL.createObjectURL(file);setPreviewSrc(url);return()=>URL.revokeObjectURL(url);},[file]);
  useEffect(()=>{const id=searchParams.get("analysis");if(id)api<Analysis>(`/analisis/${id}`).then(setAnalysis).catch(e=>setError(message(e)));},[searchParams]);
  useEffect(()=>{if(!analysis||["COMPLETED","FAILED"].includes(analysis.status))return; const timer=window.setInterval(()=>api<Analysis>(`/analisis/${analysis.id}`).then(setAnalysis).catch(e=>setError(message(e))),2000); return()=>window.clearInterval(timer);},[analysis]);
  useEffect(()=>{if(analysis?.status==="COMPLETED")api<Metrics>(`/analisis/${analysis.id}/metricas`).then(setMetrics).catch(e=>setError(message(e)));},[analysis?.status,analysis?.id]);
  useEffect(()=>{if(!analysis||!metrics)return;let objectUrl="";let cancelled=false;Promise.all([api<AnalysisFrames>(`/analisis/${analysis.id}/frames`),apiBlob(`/videos/${analysis.video_id}/content`),api<Analysis[]>("/analisis")]).then(([frames,blob,all])=>{if(cancelled)return;objectUrl=URL.createObjectURL(blob);setFrameData(frames);setVideoSrc(objectUrl);setComparisons(all.filter(a=>a.id!==analysis.id&&a.status==="COMPLETED"));}).catch(e=>setError(message(e)));return()=>{cancelled=true;if(objectUrl)URL.revokeObjectURL(objectUrl);};},[analysis?.id,metrics]);
  const detailed=searchParams.get("detail")==="1";
  const nearestFrame=useMemo(()=>{if(!frameData?.frames.length)return null;return frameData.frames.reduce((nearest,frame)=>Math.abs(frame.timestamp-currentTime)<Math.abs(nearest.timestamp-currentTime)?frame:nearest);},[frameData,currentTime]);
  const chooseComparison=async(id:string)=>{setCompareId(id);setComparison(null);if(!id||!analysis)return;try{const data=await api<{metrics:Record<string,{current:number;comparison:number;difference:number}>}>(`/analisis/${analysis.id}/compare/${id}`);setComparison(data.metrics);}catch(err){setError(message(err));}};
  const selectVideo=(selectedFile?:File)=>{if(!selectedFile)return;const extension=selectedFile.name.toLowerCase().slice(selectedFile.name.lastIndexOf("."));if(![".mp4",".mov"].includes(extension)){setFile(null);setError("El archivo debe tener formato MP4 o MOV.");return;}if(selectedFile.type&&!["video/mp4","video/quicktime"].includes(selectedFile.type)){setFile(null);setError("El tipo de archivo no es compatible. Selecciona un video MP4 o MOV.");return;}if(selectedFile.size>500*1024*1024){setFile(null);setError("El video supera el límite de 500 MB.");return;}setError("");setVideoInfo({duration:0,width:0,height:0});setFile(selectedFile);};
  const handleVideoDrop=(event:React.DragEvent<HTMLLabelElement>)=>{event.preventDefault();setDraggingVideo(false);selectVideo(event.dataTransfer.files[0]);};
  const prepare=(event:React.FormEvent)=>{event.preventDefault();if(!file){setError("Selecciona un video MP4 o MOV.");return;}if(file.size>500*1024*1024){setError("El video supera el límite de 500 MB.");return;}setError("");setPreview(true);};
  const create = async()=>{if(!file){setError("Selecciona un video MP4 o MOV.");return;}setBusy(true);setError("");try{
    let athleteId=Number(selected);
    if(!athleteId){const athlete=await api<Athlete>("/atletas",{method:"POST",body:JSON.stringify({first_name:name.split(" ")[0],last_name:name.split(" ").slice(1).join(" ")||"Atleta",identification,age:Number(athleteAge),gender:athleteGender})});athleteId=athlete.id;}
    const test=await api<Test>("/pruebas",{method:"POST",body:JSON.stringify({athlete_id:athleteId,distance:Number(distance),test_type:testType,technique,test_date:date})});
    const body=new FormData(); body.append("video",file);
    const result=await api<{analysis_id:number;video_id:number;status:string}>(`/analisis/procesar-video?test_id=${test.id}`,{method:"POST",body});
    setAnalysis({id:result.analysis_id,video_id:result.video_id,status:result.status,progress_percentage:0});
  }catch(err){setError(message(err));}finally{setBusy(false);}};
  const reprocess = async()=>{if(!analysis)return;setBusy(true);setError("");try{const result=await api<{analysis_id:number;status:string}>("/analisis",{method:"POST",body:JSON.stringify({video_id:analysis.video_id})});setMetrics(null);setFrameData(null);setVideoSrc("");setAnalysis({id:result.analysis_id,video_id:analysis.video_id,status:result.status,progress_percentage:0});setSearchParams({analysis:String(result.analysis_id),detail:"1"});}catch(err){setError(message(err));}finally{setBusy(false);}};
  if(analysis) return <><button className="back-link" onClick={()=>{setAnalysis(null);setMetrics(null);}}><ArrowLeft size={16}/> Nuevo análisis</button><PageTitle eyebrow="PROCESAMIENTO" title={metrics?"Resultados del análisis":"Analizando video"} subtitle={metrics?"Resumen biomecánico de la prueba.":"El video está en proceso; esta pantalla se actualizará automáticamente."}/>{error&&<ErrorBanner text={error}/>}
    {!metrics&&<section className="panel progress-panel"><div className="progress-head"><div className="progress-spinner"><Activity/></div><div><h2>{analysis.status==="FAILED"?"No se pudo procesar el video":"Procesando movimiento"}</h2><p>{analysis.status==="FAILED"?analysis.error_message:"Detección del atleta · análisis biomecánico · generación de resultados"}</p></div><strong>{analysis.progress_percentage}%</strong></div><div className="progress-track"><span style={{width:`${analysis.progress_percentage}%`}}/></div><div className="steps"><span className="step done"><Check/> Video cargado</span><span className={analysis.progress_percentage>=25?"step done":"step"}>Detección del atleta</span><span className={analysis.progress_percentage>=60?"step done":"step"}>Análisis del movimiento</span><span className={analysis.progress_percentage>=90?"step done":"step"}>Generación de resultados</span></div></section>}
    {metrics&&<><div className="metric-grid"><MetricCard label="Velocidad promedio" value={`${metrics.average_speed.toFixed(2)}`} unit="m/s" icon={<Activity/>}/><MetricCard label="Longitud de zancada" value={`${metrics.stride_length.toFixed(2)}`} unit="m" icon={<ArrowRight/>}/><MetricCard label="Cadencia" value={`${metrics.cadence.toFixed(2)}`} unit="pasos/s" icon={<Gauge/>}/><MetricCard label="Postura" value={`${metrics.posture_score.toFixed(0)}`} unit="/ 100" icon={<ShieldCheck/>}/></div><section className="panel result-actions"><div><h2>Resultados listos</h2><p>Análisis #{analysis.id} · velocidades máximas de {metrics.maximum_speed.toFixed(2)} m/s</p></div>{detailed&&<button className="button secondary" disabled={busy} onClick={()=>void reprocess()}>{busy?"Encolando…":"Reprocesar con detección real"}</button>}<button className="button secondary" onClick={()=>setSearchParams(detailed?{}:{analysis:String(analysis.id),detail:"1"})}>{detailed?"Ocultar detalle":"Ver análisis detallado"}</button><button className="button primary" onClick={()=>download(`/analisis/${analysis.id}/reporte`,`analisis-${analysis.id}.pdf`)}><ArrowDownToLine size={16}/> Exportar PDF</button><Link className="button secondary" to={`/reportes?analysis=${analysis.id}`}>Crear reporte</Link></section>
      {detailed&&<><section className="detail-grid"><div className="panel player-panel"><div className="panel-heading"><div><h2>Reproducción biomecánica</h2><p>Video y puntos corporales detectados por cuadro</p></div><span className="badge processing">{nearestFrame?`${nearestFrame.speed.toFixed(2)} m/s`:"Cargando"}</span></div>{videoSrc&&frameData&&<div className="video-stage"><video ref={player} src={videoSrc} controls preload="metadata" onTimeUpdate={e=>setCurrentTime(e.currentTarget.currentTime)}/><svg className="pose-overlay" viewBox={`0 0 ${frameData.width||1920} ${frameData.height||1080}`} preserveAspectRatio="none">{nearestFrame&&<PoseOverlay points={nearestFrame.keypoints}/>}</svg></div>}<div className="video-foot"><span>{nearestFrame?`Cuadro ${nearestFrame.frame_number+1} · ${nearestFrame.keypoints.length?`${nearestFrame.keypoints.length} puntos detectados`:"No se detectó cuerpo en este cuadro"}`:"Cargando datos del video"}</span><span>{nearestFrame?`${nearestFrame.timestamp.toFixed(2)} s`:""}</span></div></div><section className="panel comparison-panel"><div className="panel-heading"><div><h2>Comparar prueba</h2><p>Compara resultados con otro análisis completado.</p></div></div><label>Análisis de referencia<select value={compareId} onChange={e=>void chooseComparison(e.target.value)}><option value="">Selecciona una prueba</option>{comparisons.map(item=><option key={item.id} value={item.id}>Análisis #{item.id}</option>)}</select></label>{comparison&&<div className="compare-list">{Object.entries(comparison).map(([key,value])=><div key={key}><span>{metricLabel(key)}</span><b>{value.current.toFixed(2)}</b><span className={value.difference>=0?"positive":"negative"}>{value.difference>=0?"+":""}{value.difference.toFixed(2)}</span></div>)}</div>}</section></section>
      <section className="timeline-grid"><MetricChart title="Velocidad" unit="m/s" frames={frameData?.frames??[]} value={f=>f.speed}/><MetricChart title="Cadencia estimada" unit="eventos/s" frames={frameData?.frames??[]} value={(f,i,all)=>all.slice(Math.max(0,i-29),i+1).filter(frame=>frame.stride_phase==="apoyo").length/(Math.max(f.timestamp-all[Math.max(0,i-29)].timestamp,0.1))}/><MetricChart title="Longitud de zancada estimada" unit="m" frames={frameData?.frames??[]} value={(f,i,all)=>{const previous=all.slice(0,i).reverse().find(frame=>frame.stride_phase==="apoyo");return previous?Math.hypot(f.x_position-previous.x_position,f.y_position-previous.y_position):0}}/></section>
      <section className="panel feedback-panel"><div className="panel-heading"><div><h2>Evaluación de postura</h2><p>Orientación biomecánica basada en los cuadros procesados.</p></div></div><div className="feedback-grid"><FeedbackCard title="Postura general" value={metrics.posture_score} description={`Puntuación media: ${metrics.posture_score.toFixed(1)} / 100`}/><FeedbackCard title="Control de velocidad" value={metrics.average_speed>0?75:0} description={`Promedio ${metrics.average_speed.toFixed(2)} · máximo ${metrics.maximum_speed.toFixed(2)} m/s`}/><FeedbackCard title="Ritmo de zancada" value={metrics.cadence>0?70:0} description={`${metrics.cadence.toFixed(2)} pasos por segundo`}/></div></section></>}</>}
  </>;
  if(preview&&file)return <><button className="back-link" onClick={()=>setPreview(false)}><ArrowLeft size={16}/> Volver a editar</button><PageTitle eyebrow="PASO 2 · PREPARAR ANÁLISIS" title="Revisar video" subtitle="Confirma la grabación y los datos de la prueba antes de iniciar el procesamiento."/><div className="preview-layout"><section className="panel preview-video">{previewSrc&&<video src={previewSrc} controls onLoadedMetadata={e=>setVideoInfo({duration:e.currentTarget.duration,width:e.currentTarget.videoWidth,height:e.currentTarget.videoHeight})}/>}</section><section className="panel preview-summary"><span className="eyebrow">RESUMEN DE LA PRUEBA</span><h2>{selected?athletes.find(a=>String(a.id)===selected)?.first_name+" "+athletes.find(a=>String(a.id)===selected)?.last_name:name}</h2><div className="summary-row"><span>Archivo</span><b>{file.name}</b></div><div className="summary-row"><span>Duración</span><b>{videoInfo.duration?`${videoInfo.duration.toFixed(2)} s`:"Metadatos cargando…"}</b></div><div className="summary-row"><span>Resolución</span><b>{videoInfo.width?`${videoInfo.width} × ${videoInfo.height}`:"—"}</b></div><div className="summary-row"><span>Distancia</span><b>{distance} m</b></div><div className="summary-row"><span>Tipo / técnica</span><b>{testType} · {technique}</b></div><div className="summary-row"><span>Fecha</span><b>{formatDate(date)}</b></div>{error&&<ErrorBanner text={error}/>}<button className="button primary full" disabled={busy} onClick={()=>void create()}>{busy?"Subiendo y preparando…":"Comenzar análisis"} <ArrowRight size={16}/></button></section></div></>;
  return <><PageTitle eyebrow="PASO 1 · INFORMACIÓN DE LA PRUEBA" title="Nuevo análisis" subtitle="Registra los datos del atleta y selecciona el video de la prueba."/><form onSubmit={prepare}><div className="analysis-form-grid"><section className="panel form-panel"><div className="form-section-title"><span className="step-number">01</span><div><h2>Información de la prueba</h2><p>Datos del atleta y las condiciones de la carrera.</p></div></div><label>Atleta existente<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Seleccionar atleta (o registrar uno nuevo)</option>{athletes.map(a=><option key={a.id} value={a.id}>{a.first_name} {a.last_name} · {a.identification}</option>)}</select></label>{!selected&&<><div className="field-row"><label>Nombre del estudiante<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Nombre y apellidos"/></label><label>Documento<input required value={identification} onChange={e=>setIdentification(e.target.value)} placeholder="Número de documento"/></label></div><div className="field-row"><label>Edad<input type="number" min="1" max="120" required value={athleteAge} onChange={e=>setAthleteAge(e.target.value)}/></label><label>Género<select value={athleteGender} onChange={e=>setAthleteGender(e.target.value)}><option>Femenino</option><option>Masculino</option><option>Otro</option><option>No especificado</option></select></label></div></>}<div className="field-row"><label>Fecha<input type="date" required value={date} onChange={e=>setDate(e.target.value)}/></label><label>Distancia (m)<select value={distance} onChange={e=>setDistance(e.target.value)}>{["10","20","30","40","60","100"].map(n=><option key={n}>{n}</option>)}</select></label></div><label>Tipo de prueba<select value={testType} onChange={e=>setTestType(e.target.value)}><option>Carrera de velocidad</option><option>Aceleración</option><option>Velocidad máxima</option></select></label><label>Técnica<select value={technique} onChange={e=>setTechnique(e.target.value)}><option>Salida de tacos</option><option>Salida de pie</option></select></label></section>
    <section className="panel upload-panel"><div className="form-section-title"><span className="step-number">02</span><div><h2>Video de la prueba</h2><p>Sube una grabación clara de la carrera.</p></div></div><label className={`dropzone ${file?"has-file":""} ${draggingVideo?"dragging":""}`} onDragOver={event=>{event.preventDefault();setDraggingVideo(true);}} onDragLeave={()=>setDraggingVideo(false)} onDrop={handleVideoDrop}><input type="file" accept="video/mp4,video/quicktime,.mp4,.mov" onChange={e=>selectVideo(e.target.files?.[0])}/><span className="upload-icon"><Video size={25}/></span><b>{file?file.name:draggingVideo?"Suelta el video para cargarlo":"Arrastra tu video aquí"}</b><span>{file?`${(file.size/1024/1024).toFixed(1)} MB`:"o selecciónalo desde tu dispositivo"}</span><span className="button secondary choose-button">Seleccionar video</span><small>Formatos admitidos: MP4, MOV · Máximo 500 MB</small></label></section></div>
    {error&&<ErrorBanner text={error}/>}<div className="form-actions"><button className="button secondary" type="reset" onClick={()=>{setFile(null);setError("");}}>Cancelar</button><button className="button primary">Continuar <ArrowRight size={16}/></button></div></form></>;
}

function AthletesPage() {
  const [data,setData]=useState<Athlete[]>([]);const [search,setSearch]=useState("");const [status,setStatus]=useState("all");const [category,setCategory]=useState("");const [group,setGroup]=useState("");const [groups,setGroups]=useState<{categories:string[];groups:string[]}>({categories:[],groups:[]});const [totalTests,setTotalTests]=useState(0);const [error,setError]=useState("");const [modal,setModal]=useState(false);const [editing,setEditing]=useState<Athlete|null>(null);const importRef=useRef<HTMLInputElement>(null);
  const load=useCallback(()=>{const params=new URLSearchParams({limit:"200"});if(search.trim())params.set("q",search.trim());if(status!=="all")params.set("is_active",status);if(category)params.set("category",category);if(group)params.set("group_name",group);api<Athlete[]>(`/atletas?${params}`).then(setData).catch(e=>setError(message(e)));},[search,status,category,group]);
  useEffect(()=>{void load();api<{categories:string[];groups:string[]}>("/atletas/groups").then(setGroups).catch(e=>setError(message(e)));api<{total:number}>("/pruebas/summary").then(s=>setTotalTests(s.total)).catch(e=>setError(message(e)));},[load]);
  async function importFile(file?:File){if(!file)return;const body=new FormData();body.append("file",file);setError("");try{const result=await api<{imported:number}>("/atletas/import",{method:"POST",body});setError(`${result.imported} atletas importados correctamente.`);void load();}catch(err){setError(message(err));}}
  async function toggleActive(athlete:Athlete){try{if(athlete.is_active)await api(`/atletas/${athlete.id}`,{method:"DELETE"});else await api(`/atletas/${athlete.id}`,{method:"PUT",body:JSON.stringify({is_active:true})});void load();}catch(err){setError(message(err));}}
  return <><PageTitle eyebrow="GESTIÓN DE ATLETAS" title="Atletas" subtitle="Administra el padrón de estudiantes deportistas." action={<div className="toolbar-actions"><button className="button secondary" onClick={()=>void download("/atletas/export","atletas.csv")}><ArrowDownToLine size={15}/> Exportar</button><button className="button secondary" onClick={()=>importRef.current?.click()}><Plus size={15}/> Importar CSV</button><input ref={importRef} hidden type="file" accept=".csv,text/csv" onChange={e=>void importFile(e.target.files?.[0])}/><button className="button primary" onClick={()=>setModal(true)}><Plus size={17}/> Nuevo atleta</button></div>}/>{error&&<ErrorBanner text={error}/>}<div className="stat-grid three"><StatCard label="Atletas registrados" value={data.length} icon={<Users/>} color="blue"/><StatCard label="Atletas activos en vista" value={data.filter(a=>a.is_active).length} icon={<Activity/>} color="green"/><StatCard label="Pruebas realizadas" value={totalTests} icon={<ClipboardList/>} color="violet"/></div><section className="panel table-panel"><div className="table-toolbar"><div><h2>Listado de atletas</h2><p>{data.length} resultados · filtros por categoría y grupo</p></div><div className="athlete-filters"><div className="search-box"><Search size={17}/><input placeholder="Buscar nombre o documento" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todos los estados</option><option value="true">Activos</option><option value="false">Inactivos</option></select><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">Todas las categorías</option>{groups.categories.map(value=><option key={value}>{value}</option>)}</select><select value={group} onChange={e=>setGroup(e.target.value)}><option value="">Todos los grupos</option>{groups.groups.map(value=><option key={value}>{value}</option>)}</select></div></div>{data.length?<div className="table-scroll"><table><thead><tr><th>ATLETA</th><th>DOCUMENTO / CORREO</th><th>EDAD</th><th>CATEGORÍA · GRUPO</th><th>PRUEBAS</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>{data.map(a=><tr key={a.id}><td><Link className="athlete-cell" to={`/atletas/${a.id}`}><span className="avatar">{initials(a.first_name,a.last_name)}</span><b>{a.first_name} {a.last_name}</b></Link></td><td>{a.identification}<small className="cell-sub">{a.email||"Sin correo"}</small></td><td>{a.age} años</td><td>{a.category||"—"}<small className="cell-sub">{a.group_name||"Sin grupo"}</small></td><td>{a.test_count??0}</td><td><span className={`badge ${a.is_active?"success":"pending"}`}>{a.is_active?"Activo":"Inactivo"}</span></td><td><div className="table-actions"><button className="text-link" onClick={()=>setEditing(a)}>Editar</button><button className="text-link" onClick={()=>void toggleActive(a)}>{a.is_active?"Desactivar":"Activar"}</button><Link className="row-arrow" to={`/atletas/${a.id}`} aria-label="Ver perfil"><ArrowRight size={16}/></Link></div></td></tr>)}</tbody></table></div>:<Empty title="No hay atletas para mostrar" detail="Ajusta los filtros o registra el primer atleta."/>}</section>{(modal||editing)&&<AthleteModal athlete={editing??undefined} onClose={()=>{setModal(false);setEditing(null);}} onCreated={()=>{setModal(false);setEditing(null);void load();}}/>}</>;
}

function AthleteModal({onClose,onCreated,athlete}:{onClose:()=>void;onCreated:()=>void;athlete?:Athlete}) {
  const [error,setError]=useState(""); const [busy,setBusy]=useState(false);
  async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");const values=Object.fromEntries(new FormData(e.currentTarget));const payload={first_name:values.first_name,last_name:values.last_name,identification:values.identification,age:Number(values.age),gender:values.gender,email:values.email||null,category:values.category||null,group_name:values.group_name||null};try{await api(athlete?`/atletas/${athlete.id}`:"/atletas",{method:athlete?"PUT":"POST",body:JSON.stringify(payload)});onCreated();}catch(err){setError(message(err));}finally{setBusy(false);}}
  return <div className="modal-backdrop" onMouseDown={onClose}><form className="modal-card" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><button type="button" className="modal-close" onClick={onClose}><X/></button><span className="eyebrow">PADRÓN DEPORTIVO</span><h2>{athlete?"Editar atleta":"Nuevo atleta"}</h2><p>Completa los datos del estudiante.</p><div className="field-row"><label>Nombre<input name="first_name" required defaultValue={athlete?.first_name}/></label><label>Apellidos<input name="last_name" required defaultValue={athlete?.last_name}/></label></div><label>Documento<input name="identification" required defaultValue={athlete?.identification}/></label><label>Correo electrónico<input type="email" name="email" defaultValue={athlete?.email??""}/></label><div className="field-row"><label>Edad<input type="number" name="age" min="1" max="120" required defaultValue={athlete?.age}/></label><label>Género<select name="gender" defaultValue={athlete?.gender??"Femenino"}><option>Femenino</option><option>Masculino</option><option>Otro</option></select></label></div><div className="field-row"><label>Categoría<input name="category" defaultValue={athlete?.category??""}/></label><label>Grupo<input name="group_name" defaultValue={athlete?.group_name??""}/></label></div>{error&&<ErrorBanner text={error}/>}<div className="form-actions"><button type="button" className="button secondary" onClick={onClose}>Cancelar</button><button disabled={busy} className="button primary">{busy?"Guardando…":"Guardar atleta"}</button></div></form></div>;
}

function AthleteDetail() {
  const {pathname}=useLocation();const id=pathname.split("/").pop();const [athlete,setAthlete]=useState<Athlete|null>(null);const [history,setHistory]=useState<Array<{test_id:number;date:string;distance:number;status:string;analysis_id:number|null;average_speed:number|null;maximum_speed:number|null;stride_length:number|null;cadence:number|null;posture_score:number|null}>>([]);const [summary,setSummary]=useState<{total_tests:number;average_speed:number|null;best_speed:number|null}>({total_tests:0,average_speed:null,best_speed:null});const [error,setError]=useState("");
  useEffect(()=>{if(!id)return;Promise.all([api<Athlete>(`/atletas/${id}`),api<{history:typeof history;total_tests:number;average_speed:number|null;best_speed:number|null}>(`/atletas/${id}/metrics`)]).then(([a,m])=>{setAthlete(a);setHistory(m.history);setSummary(m);}).catch(e=>setError(message(e)));},[id]);
  return <><Link to="/atletas" className="back-link"><ArrowLeft size={16}/> Volver a atletas</Link>{error&&<ErrorBanner text={error}/>}<PageTitle eyebrow="PERFIL DEL ATLETA" title={athlete?`${athlete.first_name} ${athlete.last_name}`:"Cargando…"} subtitle={athlete?`Documento ${athlete.identification} · ${athlete.age} años · ${athlete.category??"Sin categoría"} · ${athlete.group_name??"Sin grupo"}`:""} action={<Link className="button primary" to={`/analisis?athlete=${id}`}><Plus size={16}/> Nuevo análisis</Link>}/><div className="metric-grid three"><MetricCard label="Pruebas realizadas" value={summary.total_tests} unit="pruebas" icon={<ClipboardList/>}/><MetricCard label="Velocidad promedio" value={summary.average_speed?.toFixed(2)??"—"} unit="m/s" icon={<Activity/>}/><MetricCard label="Mejor velocidad" value={summary.best_speed?.toFixed(2)??"—"} unit="m/s" icon={<Gauge/>}/></div><section className="panel chart-panel"><div className="panel-heading"><div><h2>Evolución del rendimiento</h2><p>Velocidad promedio por fecha de prueba</p></div></div><SeriesChart points={history.filter(item=>item.average_speed!==null).map(item=>({label:formatDate(item.date),value:item.average_speed??0}))}/></section><section className="panel table-panel"><div className="table-toolbar"><div><h2>Historial de pruebas</h2><p>Registro de actividad del atleta</p></div></div>{history.length?<div className="table-scroll"><table><thead><tr><th>PRUEBA</th><th>DISTANCIA</th><th>FECHA</th><th>VELOCIDAD</th><th>CADENCIA</th><th>ESTADO</th><th/></tr></thead><tbody>{history.map(t=><tr key={t.test_id}><td>PRU-{String(t.test_id).padStart(5,"0")}</td><td>{t.distance} m</td><td>{formatDate(t.date)}</td><td>{t.average_speed?.toFixed(2)??"—"} m/s</td><td>{t.cadence?.toFixed(2)??"—"} pasos/s</td><td><StatusBadge status={t.status}/></td><td>{t.analysis_id&&<Link className="row-arrow" to={`/analisis?analysis=${t.analysis_id}`}><ArrowRight size={16}/></Link>}</td></tr>)}</tbody></table></div>:<Empty title="Sin pruebas registradas" detail="Las pruebas asociadas aparecerán en esta lista."/>}</section></>;
}

function TestsPage() {
  const [tests,setTests]=useState<Test[]>([]);const [athletes,setAthletes]=useState<Athlete[]>([]);const [summary,setSummary]=useState({total:0,this_month:0,completed:0,processing:0});const [filteredTotal,setFilteredTotal]=useState(0);const [search,setSearch]=useState("");const [status,setStatus]=useState("");const [dateFrom,setDateFrom]=useState("");const [dateTo,setDateTo]=useState("");const [page,setPage]=useState(0);const [error,setError]=useState("");const pageSize=25;
  useEffect(()=>{const params=new URLSearchParams({skip:String(page*pageSize),limit:String(pageSize)});if(search.trim())params.set("q",search.trim());if(status)params.set("status",status);if(dateFrom)params.set("date_from",dateFrom);if(dateTo)params.set("date_to",dateTo);apiPage<Test[]>(`/pruebas?${params}`).then(result=>{setTests(result.items);setFilteredTotal(result.total);}).catch(e=>setError(message(e)));},[search,status,dateFrom,dateTo,page]);
  useEffect(()=>{Promise.all([api<Athlete[]>("/atletas?limit=200"),api<typeof summary>("/pruebas/summary")]).then(([a,s])=>{setAthletes(a);setSummary(s);}).catch(e=>setError(message(e)));},[]);
  const athleteMap=useMemo(()=>new Map(athletes.map(a=>[a.id,`${a.first_name} ${a.last_name}`])),[athletes]);
  const completedPages=Math.ceil(filteredTotal/pageSize);
  return <><PageTitle eyebrow="HISTORIAL GENERAL" title="Pruebas" subtitle="Consulta las ejecuciones y el estado de cada evaluación." action={<Link className="button primary" to="/analisis"><Plus size={17}/> Nueva prueba</Link>}/>{error&&<ErrorBanner text={error}/>}<div className="stat-grid four"><StatCard label="Total pruebas" value={summary.total} icon={<ClipboardList/>} color="blue"/><StatCard label="Este mes" value={summary.this_month} icon={<Clock3/>} color="violet"/><StatCard label="Completadas" value={summary.completed} icon={<Check/>} color="green"/><StatCard label="En proceso" value={summary.processing} icon={<Activity/>} color="amber"/></div><section className="panel table-panel"><div className="table-toolbar"><div><h2>Todas las pruebas</h2><p>{filteredTotal} resultados · página {page+1} de {Math.max(completedPages,1)}</p></div><div className="test-filters"><div className="search-box"><Search size={17}/><input placeholder="Buscar prueba o atleta" value={search} onChange={e=>{setPage(0);setSearch(e.target.value);}}/></div><select value={status} onChange={e=>{setPage(0);setStatus(e.target.value);}}><option value="">Todos los estados</option><option value="COMPLETED">Completado</option><option value="PROCESSING">Procesando</option><option value="PENDING">Pendiente</option><option value="CANCELLED">Cancelado</option></select><label className="date-filter">Desde<input type="date" value={dateFrom} onChange={e=>{setPage(0);setDateFrom(e.target.value);}}/></label><label className="date-filter">Hasta<input type="date" value={dateTo} onChange={e=>{setPage(0);setDateTo(e.target.value);}}/></label></div></div>{tests.length?<div className="table-scroll"><table><thead><tr><th>CÓDIGO</th><th>ATLETA</th><th>TIPO / TÉCNICA</th><th>DISTANCIA</th><th>FECHA</th><th>VELOCIDAD</th><th>ESTADO</th></tr></thead><tbody>{tests.map(t=><tr key={t.id}><td className="code">PRU-{String(t.id).padStart(5,"0")}</td><td>{athleteMap.get(t.athlete_id)??`Atleta #${t.athlete_id}`}</td><td>{t.test_type}<small className="cell-sub">{t.technique}</small></td><td>{t.distance} m</td><td>{formatDate(t.created_at)}</td><td>{t.average_speed==null?"—":`${t.average_speed.toFixed(2)} m/s`}</td><td><StatusBadge status={t.analysis_status??t.status}/></td></tr>)}</tbody></table></div>:<Empty title="No hay pruebas para mostrar" detail="Ajusta los filtros o crea una nueva prueba."/>}<div className="pagination"><button className="button secondary" disabled={page===0} onClick={()=>setPage(n=>n-1)}><ArrowLeft size={14}/> Anterior</button><span>Página {page+1} de {Math.max(completedPages,1)}</span><button className="button secondary" disabled={page+1>=completedPages} onClick={()=>setPage(n=>n+1)}>Siguiente <ArrowRight size={14}/></button></div></section></>;
}

function ReportsPage() {
  const [reports,setReports]=useState<Report[]>([]);const [analyses,setAnalyses]=useState<Analysis[]>([]);const [athletes,setAthletes]=useState<Athlete[]>([]);const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [template,setTemplate]=useState("individual");const [selectedMetrics,setSelectedMetrics]=useState(["average_speed","maximum_speed","stride_length","cadence","posture_score"]);const [analysisParam]=useSearchParams();
  const refresh=useCallback(()=>api<Report[]>("/reports").then(setReports).catch(e=>setError(message(e))),[]);
  useEffect(()=>{void refresh();api<Analysis[]>("/analisis?limit=200").then(setAnalyses).catch(e=>setError(message(e)));api<Athlete[]>("/atletas?limit=200").then(setAthletes).catch(e=>setError(message(e)));},[refresh]);
  async function generate(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const formElement=e.currentTarget;const form=new FormData(formElement);const athleteSelect=formElement.elements.namedItem("athlete_ids") as HTMLSelectElement;const metrics=Array.from(formElement.querySelectorAll<HTMLInputElement>('input[name="metrics"]:checked')).map(input=>input.value);setBusy(true);setError("");try{await api("/reports/generate",{method:"POST",body:JSON.stringify({name:form.get("name"),output_format:form.get("format"),template,analysis_id:form.get("analysis_id")?Number(form.get("analysis_id")):null,athlete_ids:Array.from(athleteSelect.selectedOptions).map(option=>Number(option.value)),date_from:form.get("date_from")||null,date_to:form.get("date_to")||null,metrics})});await refresh();formElement.reset();}catch(err){setError(message(err));}finally{setBusy(false);}}
  const downloads=reports.reduce((sum,report)=>sum+(report.downloads??0),0);
  return <><PageTitle eyebrow="INFORMES ANALÍTICOS" title="Reportes" subtitle="Genera informes con filtros, plantillas y métricas seleccionadas."/><div className="stat-grid three"><StatCard label="Reportes generados" value={reports.length} icon={<FileBarChart/>} color="blue"/><StatCard label="Este mes" value={reports.filter(r=>r.created_at?.slice(0,7)===new Date().toISOString().slice(0,7)).length} icon={<Clock3/>} color="violet"/><StatCard label="Descargas totales" value={downloads} icon={<ArrowDownToLine/>} color="green"/></div><div className="two-column"><section className="panel form-panel"><span className="eyebrow">NUEVO REPORTE</span><h2>Configurar informe</h2><p>Define la plantilla, el rango y las métricas del análisis.</p><form onSubmit={generate} className="stack-form"><label>Nombre del reporte<input name="name" required placeholder="Informe de rendimiento"/></label><label>Plantilla<select value={template} onChange={e=>setTemplate(e.target.value)}><option value="monthly">Informe mensual</option><option value="individual">Evolución individual</option><option value="group">Comparativa grupal</option><option value="trends">Análisis de tendencias</option></select></label><label>Análisis específico (opcional)<select name="analysis_id" defaultValue={analysisParam.get("analysis")??""}><option value="">Usar atletas y rango de fechas</option>{analyses.filter(a=>a.status==="COMPLETED").map(a=><option key={a.id} value={a.id}>Análisis #{a.id} · video #{a.video_id}</option>)}</select></label><label>Atletas (opcional; Ctrl/Cmd para varios)<select name="athlete_ids" multiple size={4}>{athletes.map(a=><option key={a.id} value={a.id}>{a.first_name} {a.last_name}</option>)}</select></label><div className="field-row"><label>Desde<input name="date_from" type="date"/></label><label>Hasta<input name="date_to" type="date"/></label></div><fieldset className="metric-options"><legend>Métricas a incluir</legend>{[["average_speed","Velocidad promedio"],["maximum_speed","Velocidad máxima"],["stride_length","Zancada"],["cadence","Cadencia"],["posture_score","Postura"]].map(([value,label])=><label key={value}><input type="checkbox" name="metrics" value={value} checked={selectedMetrics.includes(value)} onChange={e=>setSelectedMetrics(current=>e.target.checked?[...current,value]:current.filter(item=>item!==value))}/>{label}</label>)}</fieldset><label>Formato de salida<select name="format"><option value="pdf">PDF</option><option value="xlsx">Excel (.xlsx)</option><option value="csv">CSV</option></select></label>{error&&<ErrorBanner text={error}/>}<button className="button primary" disabled={busy}><FileBarChart size={16}/>{busy?"Generando…":"Generar reporte"}</button></form></section><section className="panel table-panel report-list"><div className="table-toolbar"><div><h2>Mis reportes</h2><p>Informes generados recientemente</p></div></div>{reports.length?reports.map(r=><div className="report-row" key={r.id}><span className="file-icon"><FileText/></span><span><b>{r.name}</b><small>Análisis #{r.analysis_id} · {formatDate(r.created_at)} · {r.downloads??0} descargas</small></span><span className="format-pill">{r.format.toUpperCase()}</span><button className="icon-button" title="Descargar" onClick={()=>download(r.download_url.replace("/api/v1",""),`${r.name}.${r.format}`).then(refresh).catch(e=>setError(message(e)))}><ArrowDownToLine size={17}/></button></div>):<Empty title="Todavía no hay reportes" detail="Los informes que generes aparecerán aquí."/>}</section></div></>;
}

function LibraryPage() {
  const [tab,setTab]=useState<"video"|"document"|"reference">("video");const [items,setItems]=useState<Resource[]>([]);const [references,setReferences]=useState<ReferenceRange[]>([]);const [error,setError]=useState("");const [showUpload,setShowUpload]=useState(false);const [referenceEdit,setReferenceEdit]=useState<ReferenceRange|null|undefined>(undefined);
  const refresh=useCallback(()=>api<Resource[]|ReferenceRange[]>(`/library/resources?type=${tab}`).then(data=>tab==="reference"?setReferences(data as ReferenceRange[]):setItems(data as Resource[])).catch(e=>setError(message(e))),[tab]);
  useEffect(()=>{void refresh();},[refresh]);
  async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setError("");const form=new FormData(e.currentTarget);try{await api<Resource>("/library/resources",{method:"POST",body:form});setShowUpload(false);await refresh();}catch(err){setError(message(err));}}
  async function saveReference(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));const payload={metric:values.metric,unit:values.unit,age_range:values.age_range,low:values.low,average:values.average,high:values.high,source:values.source};try{await api(referenceEdit?.id?`/library/references/${referenceEdit.id}`:"/library/references",{method:referenceEdit?.id?"PUT":"POST",body:JSON.stringify(payload)});setReferenceEdit(undefined);await refresh();}catch(err){setError(message(err));}}
  async function deleteReference(id:number){try{await api(`/library/references/${id}`,{method:"DELETE"});await refresh();}catch(err){setError(message(err));}}
  return <><PageTitle eyebrow="RECURSOS EDUCATIVOS" title="Biblioteca" subtitle="Material técnico para acompañar el desarrollo deportivo." action={tab==="reference"?<button className="button primary" onClick={()=>setReferenceEdit(null)}><Plus size={17}/> Añadir rango</button>:<button className="button primary" onClick={()=>setShowUpload(true)}><Plus size={17}/> Subir recurso</button>}/>{error&&<ErrorBanner text={error}/>}<div className="tabs"><button className={tab==="video"?"selected":""} onClick={()=>setTab("video")}><Video size={16}/> Videos</button><button className={tab==="document"?"selected":""} onClick={()=>setTab("document")}><FileText size={16}/> Documentos</button><button className={tab==="reference"?"selected":""} onClick={()=>setTab("reference")}><BarChart3 size={16}/> Referencias</button></div>{tab==="reference"?<section className="panel table-panel"><div className="table-toolbar"><div><h2>Rangos de referencia</h2><p>Rangos institucionales; valida las fuentes con el equipo técnico.</p></div></div><div className="table-scroll"><table><thead><tr><th>MÉTRICA</th><th>UNIDAD</th><th>EDAD</th><th>BAJO</th><th>PROMEDIO</th><th>ALTO</th><th>FUENTE</th><th/></tr></thead><tbody>{references.map(r=><tr key={r.id}><td><b>{r.metric}</b></td><td>{r.unit}</td><td>{r.age_range} años</td><td><span className="range-low">{r.low}</span></td><td><span className="range-mid">{r.average}</span></td><td><span className="range-high">{r.high}</span></td><td>{r.source}</td><td><div className="table-actions"><button className="text-link" onClick={()=>setReferenceEdit(r)}>Editar</button><button className="text-link danger-link" onClick={()=>void deleteReference(r.id)}>Eliminar</button></div></td></tr>)}</tbody></table></div></section>:items.length?<div className="resource-grid">{items.map(item=><article className="resource-card" key={item.id}><div className="resource-art"><span className="resource-category">{item.category}</span>{item.type==="video"?<Video size={34}/>:<FileText size={34}/>}</div><div className="resource-info"><h3>{item.title}</h3><p>{item.filename} · {formatBytes(item.size_bytes)}</p><button className="text-link" onClick={()=>download(item.download_url.replace("/api/v1",""),item.filename)}><ArrowDownToLine size={15}/> Descargar</button></div></article>)}</div>:<section className="panel"><Empty title={tab==="video"?"No hay videos en la biblioteca":"No hay documentos en la biblioteca"} detail="Sube un recurso para que esté disponible para tu equipo." action={<button className="button secondary" onClick={()=>setShowUpload(true)}><Plus size={15}/> Subir recurso</button>}/></section>}{showUpload&&<div className="modal-backdrop" onMouseDown={()=>setShowUpload(false)}><form className="modal-card" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><button type="button" className="modal-close" onClick={()=>setShowUpload(false)}><X/></button><span className="eyebrow">BIBLIOTECA</span><h2>Subir recurso</h2><label>Tipo<select name="type" defaultValue={tab==="reference"?"document":tab}><option value="video">Video</option><option value="document">Documento</option></select></label><label>Título<input name="title" required/></label><label>Categoría<select name="category"><option>Técnica</option><option>Biomecánica</option><option>Ejercicios</option><option>Postura</option><option>Documentación</option></select></label><label>Archivo<input name="file" type="file" accept=".mp4,.mov,.pdf,.xlsx,.docx,.csv" required/></label>{error&&<ErrorBanner text={error}/>}<button className="button primary">Guardar recurso</button></form></div>}{referenceEdit!==undefined&&<div className="modal-backdrop" onMouseDown={()=>setReferenceEdit(undefined)}><form className="modal-card" onSubmit={saveReference} onMouseDown={e=>e.stopPropagation()}><button type="button" className="modal-close" onClick={()=>setReferenceEdit(undefined)}><X/></button><span className="eyebrow">BIBLIOTECA</span><h2>{referenceEdit?"Editar rango":"Añadir rango de referencia"}</h2>{(["metric","unit","age_range","low","average","high","source"] as const).map(key=><label key={key}>{fieldLabel(key)}<input name={key} required defaultValue={referenceEdit?.[key]??""}/></label>)}{error&&<ErrorBanner text={error}/>}<button className="button primary">Guardar rango</button></form></div>}</>;
}

function SettingsPage({onProfileUpdated}:{onProfileUpdated:(user:CurrentUser)=>void}) {
  const sections=["profile","institution","privacy","system"] as const;const labels=["Perfil","Institución","Privacidad","Sistema"];const [section,setSection]=useState<(typeof sections)[number]>("profile");const [values,setValues]=useState<Record<string,string|boolean>>({});const [messageText,setMessageText]=useState("");const [error,setError]=useState("");const [loading,setLoading]=useState(false);const [passwordSaving,setPasswordSaving]=useState(false);const [passwords,setPasswords]=useState({current_password:"",new_password:""});const [passwordMessage,setPasswordMessage]=useState("");const [logoUrl,setLogoUrl]=useState("");
  useEffect(()=>{let url="";setError("");setMessageText("");api<Record<string,Record<string,string|boolean>>>("/settings").then(async data=>{const value=data[section]??defaults[section];setValues(section==="privacy"?{export_format:String(value.export_format??"JSON")}:section==="system"?{timezone:String(value.timezone??"America/Bogota"),language:"Español"}:value);if(section==="institution"&&value.logo_filename){const blob=await apiBlob("/settings/institution/logo");url=URL.createObjectURL(blob);setLogoUrl(url);}else setLogoUrl("");}).catch(e=>setError(message(e)));return()=>{if(url)URL.revokeObjectURL(url);};},[section]);
  function change(key:string,value:string|boolean){setValues(current=>({...current,[key]:value}));}
  async function save(e:React.FormEvent){e.preventDefault();setLoading(true);setError("");setMessageText("");try{const data=section==="privacy"?{export_format:values.export_format}:section==="system"?{timezone:values.timezone,language:"Español"}:values;await api(`/settings/${section}`,{method:"PUT",body:JSON.stringify({data})});if(section==="profile")onProfileUpdated(await api<CurrentUser>("/auth/me"));setMessageText("Cambios guardados correctamente.");}catch(err){setError(message(err));}finally{setLoading(false);}}
  async function uploadLogo(file?:File){if(!file)return;const body=new FormData();body.append("file",file);setError("");try{const result=await api<{logo_url:string;filename:string}>("/settings/institution/logo",{method:"POST",body});change("logo_filename",result.filename);setLogoUrl(URL.createObjectURL(await apiBlob("/settings/institution/logo")));setMessageText("Logo institucional actualizado.");}catch(err){setError(message(err));}}
  async function changePassword(e:React.FormEvent){e.preventDefault();setError("");setPasswordMessage("");setPasswordSaving(true);try{await api<void>("/settings/security/password",{method:"PUT",body:JSON.stringify(passwords)});setPasswords({current_password:"",new_password:""});setPasswordMessage("Contraseña actualizada.");}catch(err){setError(message(err));}finally{setPasswordSaving(false);}}
  const currentDefaults=defaults[section];
  return <><PageTitle eyebrow="PREFERENCIAS" title="Configuración" subtitle="Administra tu perfil, institución y preferencias del sistema."/><div className="settings-layout"><aside className="settings-nav">{sections.map((s,i)=><button key={s} className={section===s?"selected":""} onClick={()=>setSection(s)}>{[Users,Activity,ShieldCheck,SettingsIcon].map((Icon,j)=>i===j?<Icon size={17} key={j}/>:null)}{labels[i]}</button>)}</aside><div className="settings-content"><form className="panel settings-form" onSubmit={save}><div><span className="eyebrow">{labels[sections.indexOf(section)].toUpperCase()}</span><h2>{labels[sections.indexOf(section)]}</h2><p>Actualiza los datos y preferencias de esta sección.</p></div>{Object.entries(currentDefaults).filter(([key])=>key!=="version"&&key!=="logo_filename").map(([key,defaultValue])=><label className={typeof defaultValue==="boolean"?"toggle-row":""} key={key}><span>{fieldLabel(key)}{typeof defaultValue==="boolean"&&<small>Configura esta preferencia para tu cuenta.</small>}</span>{key==="position"?<select value={String(values[key]??"docente").toLowerCase()} onChange={e=>change(key,e.target.value)}><option value="docente">Docente</option><option value="estudiante">Estudiante</option></select>:key==="export_format"?<select value={String(values[key]??"JSON").toUpperCase()} onChange={e=>change(key,e.target.value)}><option value="JSON">JSON</option><option value="CSV">CSV</option></select>:key==="timezone"?<select value={String(values[key]??"America/Bogota")} onChange={e=>change(key,e.target.value)}><option value="America/Bogota">Bogotá (UTC-5)</option><option value="UTC">UTC</option><option value="America/Mexico_City">Ciudad de México</option><option value="America/New_York">Nueva York</option><option value="Europe/Madrid">Madrid</option></select>:key==="language"?<select value="Español" disabled><option value="Español">Español</option></select>:typeof defaultValue==="boolean"?<input type="checkbox" checked={Boolean(values[key])} onChange={e=>change(key,e.target.checked)}/>:<input type={key==="email"?"email":key==="phone"?"tel":"text"} value={String(values[key]??"")} pattern={key==="phone"?"\\+?[0-9\\s().-]{7,20}":undefined} minLength={key==="phone"?7:undefined} maxLength={key==="phone"?20:undefined} onChange={e=>change(key,e.target.value)}/>}</label>)}{section==="institution"&&<div className="logo-upload"><span>Logo institucional</span>{logoUrl&&<img src={logoUrl} alt="Logo institucional"/>}<label className="button secondary">Subir logo<input type="file" accept=".png,.jpg,.jpeg,.webp" onChange={e=>void uploadLogo(e.target.files?.[0])}/></label></div>}{section==="privacy"&&<div className="export-actions"><button type="button" className="button secondary" onClick={()=>download(`/settings/export?format=${String(values.export_format??"JSON").toLowerCase()}`,`athletic-analysis-data.${String(values.export_format??"JSON").toLowerCase()}`).catch(e=>setError(message(e)))}>Exportar mis datos</button></div>}{error&&<ErrorBanner text={error}/>}<div className="form-actions">{messageText&&<span className="success-text"><Check size={16}/>{messageText}</span>}<button className="button primary" disabled={loading}>{loading?"Guardando…":"Guardar cambios"}</button></div></form>{section==="profile"&&<form className="panel password-form" onSubmit={changePassword}><div><h2>Cambiar contraseña</h2><p>Usa al menos 10 caracteres para proteger tu cuenta.</p></div><label>Contraseña actual<input type="password" value={passwords.current_password} onChange={e=>setPasswords(v=>({...v,current_password:e.target.value}))} required/></label><label>Nueva contraseña<input type="password" minLength={10} value={passwords.new_password} onChange={e=>setPasswords(v=>({...v,new_password:e.target.value}))} required/></label>{passwordMessage&&<span className="success-text"><Check size={16}/>{passwordMessage}</span>}<button className="button secondary" disabled={passwordSaving}>{passwordSaving?"Actualizando…":"Actualizar contraseña"}</button></form>}</div></div></>;
}

const defaults:Record<string,Record<string,string|boolean>>={
  profile:{first_name:"",last_name:"",email:"",phone:"",position:""},
  institution:{name:"",tax_id:"",email:"",address:"",city:"",phone:""},
  privacy:{export_format:"JSON"},
  system:{timezone:"America/Bogota",language:"Español"},
};

function PageTitle({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle:string;action?:React.ReactNode}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function StatCard({label,value,icon,color,note}:{label:string;value:React.ReactNode;icon:React.ReactNode;color:string;note?:string}){return <div className="stat-card"><span className={`stat-icon ${color}`}>{icon}</span><div><small>{label}</small><strong>{value??"—"}</strong>{note&&<span className="stat-note">{note}</span>}</div></div>}
function MetricCard({label,value,unit,icon}:{label:string;value:React.ReactNode;unit:string;icon:React.ReactNode}){return <div className="metric-card"><div className="metric-icon">{icon}</div><small>{label}</small><div><strong>{value}</strong><span>{unit}</span></div><div className="metric-range"><span style={{width:"64%"}}/></div><small className="range-caption">Rango de rendimiento</small></div>}
function LearnCard({icon,title,desc,color}:{icon:React.ReactNode;title:string;desc:string;color:string}){return <div className="learn-card"><span className={`learn-icon ${color}`}>{icon}</span><b>{title}</b><p>{desc}</p></div>}
function StatusBadge({status}:{status:string}){const s=status.toUpperCase();const state=["COMPLETED","COMPLETADO"].includes(s)?"success":["FAILED","CANCELLED","CANCELADO"].includes(s)?"danger":["PROCESSING","PROCESANDO"].includes(s)?"processing":"pending";const text=({COMPLETED:"Completado",COMPLETADO:"Completado",PROCESSING:"Procesando",PROCESANDO:"Procesando",PENDING:"Pendiente",FAILED:"Fallido",CANCELLED:"Cancelado",CANCELADO:"Cancelado"} as Record<string,string>)[s]??status;return <span className={`badge ${state}`}>{text}</span>}
function PoseOverlay({points}:{points:FrameDatum["keypoints"]}){const byName=new Map(points.map(point=>[point.name,point]));const bones=[["nose","left_shoulder"],["nose","right_shoulder"],["left_shoulder","right_shoulder"],["left_shoulder","left_elbow"],["left_elbow","left_wrist"],["right_shoulder","right_elbow"],["right_elbow","right_wrist"],["left_shoulder","left_hip"],["right_shoulder","right_hip"],["left_hip","right_hip"],["left_hip","left_knee"],["left_knee","left_ankle"],["right_hip","right_knee"],["right_knee","right_ankle"]];return <g>{bones.map(([from,to])=>{const a=byName.get(from),b=byName.get(to);return a&&b?<line key={`${from}-${to}`} x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke="#9dffdd" strokeWidth="8" strokeLinecap="round" opacity=".85"/>:null})}{points.map(point=><circle key={point.name} cx={point.x} cy={point.y} r="10" fill="#ffd45e" stroke="#fff" strokeWidth="3" opacity={point.confidence}/>)}</g>}
function SeriesChart({points}:{points:Array<{label:string;value:number}>}){if(points.length<2)return <div className="chart-empty">Se necesitan al menos dos pruebas con resultados para mostrar la evolución.</div>;const values=points.map(point=>point.value);const min=Math.min(...values),max=Math.max(...values);const coordinates=values.map((value,index)=>`${10+(index/Math.max(1,values.length-1))*480},${145-((value-min)/Math.max(.001,max-min))*120}`).join(" ");return <svg className="timeline-chart" viewBox="0 0 500 165" role="img" aria-label="Evolución de la velocidad promedio"><polyline fill="none" stroke="#3672ed" strokeWidth="3" strokeLinejoin="round" points={coordinates}/>{values.map((value,index)=><circle key={`${points[index].label}-${index}`} cx={10+(index/Math.max(1,values.length-1))*480} cy={145-((value-min)/Math.max(.001,max-min))*120} r="4" fill="#fff" stroke="#3672ed" strokeWidth="2"/>)}<text x="10" y="160" fill="#93a0b2" fontSize="9">{points[0].label}</text><text x="440" y="160" fill="#93a0b2" fontSize="9">{points[points.length-1].label}</text></svg>}
function MetricChart({title,unit,frames,value}:{title:string;unit:string;frames:FrameDatum[];value:(frame:FrameDatum,index:number,all:FrameDatum[])=>number}){const values=frames.map((frame,index)=>value(frame,index,frames)).filter(Number.isFinite);const min=Math.min(0,...values),max=Math.max(1,...values);const points=values.map((number,index)=>`${(index/Math.max(1,values.length-1))*480+10},${145-((number-min)/Math.max(.001,max-min))*125}`).join(" ");return <section className="panel chart-panel"><div className="panel-heading"><div><h2>{title}</h2><p>{unit} · evolución durante la prueba</p></div></div>{values.length>1?<svg className="timeline-chart" viewBox="0 0 500 165" role="img" aria-label={`Gráfica de ${title}`}><line x1="10" y1="145" x2="490" y2="145" stroke="#e8edf5"/><line x1="10" y1="82" x2="490" y2="82" stroke="#edf0f5" strokeDasharray="3 5"/><polyline fill="none" stroke="#3672ed" strokeWidth="3" strokeLinejoin="round" strokeLinecap="round" points={points}/><text x="10" y="160" fill="#93a0b2" fontSize="9">0 s</text><text x="455" y="160" fill="#93a0b2" fontSize="9">{frames[frames.length-1]?.timestamp.toFixed(1)} s</text></svg>:<div className="chart-empty">Sin suficientes cuadros para generar la gráfica.</div>}</section>}
function FeedbackCard({title,value,description}:{title:string;value:number;description:string}){const level=value>=80?"positive":value>=60?"attention":"improve";const label=level==="positive"?"Correcto":level==="attention"?"Atención":"Mejora";return <div className={`feedback-card ${level}`}><div><span>{label}</span><strong>{value.toFixed(0)}<small>/ 100</small></strong></div><b>{title}</b><p>{description}</p></div>}
function metricLabel(key:string){return ({average_speed:"Velocidad promedio",maximum_speed:"Velocidad máxima",stride_length:"Longitud de zancada",cadence:"Cadencia",posture_score:"Postura"} as Record<string,string>)[key]??key}
function Empty({title,detail,action}:{title:string;detail:string;action?:React.ReactNode}){return <div className="empty-state"><div className="empty-icon"><FileBarChart/></div><h3>{title}</h3><p>{detail}</p>{action}</div>}
function ErrorBanner({text}:{text:string}){return <div className="error-banner"><X size={16}/>{text}</div>}
function message(error:unknown){return error instanceof ApiError?error.message:error instanceof Error?error.message:"Ocurrió un error inesperado."}
function formatDate(value?:string){return value?new Date(value).toLocaleDateString("es-CO",{day:"2-digit",month:"short",year:"numeric"}):"—"}
function formatBytes(n:number){return n<1024*1024?`${(n/1024).toFixed(0)} KB`:`${(n/1024/1024).toFixed(1)} MB`}
function initials(first:string,last:string){return `${first.charAt(0)}${last.charAt(0)}`.toUpperCase()}
function initialsFromName(name:string){const parts=name.trim().split(/\s+/);return `${parts[0]?.[0]??""}${parts.length>1?parts[parts.length-1][0]:""}`.toUpperCase()}
function roleLabel(role:"docente"|"estudiante"){return role==="docente"?"Docente":"Estudiante"}
function fieldLabel(key:string){return ({first_name:"Nombre",last_name:"Apellidos",email:"Correo electrónico",phone:"Teléfono",position:"Cargo",name:"Nombre",tax_id:"NIT",address:"Dirección",city:"Ciudad",export_format:"Formato de exportación",timezone:"Zona horaria",language:"Idioma"} as Record<string,string>)[key]??key.replace(/_/g," ")}

export default App;
